return ['domain'=>'capability-manager-enhanced','plural-forms'=>'nplurals=2; plural=n != 1 && n != 2 && n != 3 && (n % 10 == 4 || n % 10 == 6 || n % 10 == 9);','language'=>'fil','project-id-version'=>'PublishPress Capabilities 2.54.0','pot-creation-date'=>'2026-11-17T17:42:15+00:00','po-revision-date'=>'2026-11-17 19:06+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Capabilities'=>'PublishPress Capabilities','https://publishpress.com/capability-manager/'=>'https://publishpress.com/capability-manager/','PublishPress Capabilities is the access control plugin for WordPress. You can manage all your WordPress user roles, from Administrators to Subscribers.'=>'Ang PublishPress Capabilities ay ang access control plugin para sa WordPress. Maaari mong pamahalaan ang lahat ng iyong mga papel ng gumagamit sa WordPress, mula sa Administrators hanggang sa Subscribers.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','%1s Error: %2s  PublishPress Capabilities cannot function because another copy of the plugin is active.'=>'%1s Error: %2s  Ang PublishPress Capabilities ay hindi maaaring gumana dahil may ibang kopya ng plugin na aktibo.','This plugin can be deleted.'=>'Maaaring tanggalin ang plugin na ito.','Preview feature restriction'=>'Limitasyon sa preview na tampok','You can block pages by URL or hide Admin elements by entering a CSS class or ID. This feature is available in PublishPress Capabilities Pro.'=>'Maaari mong harangan ang mga pahina sa pamamagitan ng URL o itago ang mga elemento ng Admin sa pamamagitan ng pagpasok ng isang CSS class o ID. Ang tampok na ito ay magagamit sa PublishPress Capabilities Pro.','Upgrade to Pro'=>'Mag-upgrade sa Pro','You\'re using PublishPress Capabilities Free. The Pro version has more features and support. %sUpgrade to Pro%s'=>'Ikaw ay gumagamit ng PublishPress Capabilities Free. Ang bersyon ng Pro ay may higit pang mga tampok at suporta. %sMag-upgrade sa Pro%s','Hide CSS Elements'=